public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes name of an album of stories. If the album is owned by a supergroup or a channel chat, then requires can_edit_stories administrator right in the chat. Returns the changed album
    /// </summary>
    public Task<TdLib.TdApi.Objects.StoryAlbum> SetStoryAlbumNameAsync(long chatId = default, int storyAlbumId = default, string name = default)
    {

           using var activity =  StartCallActivity("SetStoryAlbumNameAsync", typeof(SetStoryAlbumName).FullName ?? "SetStoryAlbumNameAsync");

           try
           {
             return client.SetStoryAlbumNameAsync(chatId, storyAlbumId, name);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
